    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);
wire [7:0] A;
assign A[0] = |a_i[3:0];
assign A[1] = |a_i[7:4];
assign A[2] = |a_i[11:8];
assign A[3] = |a_i[15:12];
assign A[4] = |a_i[19:16];
assign A[5] = |a_i[23:20];
assign A[6] = |a_i[27:24];
assign A[7] = |a_i[31:28];
wire [7:0] sel;
assign sel[7] = A[7];
assign sel[6] = A[6] & ~A[7];
assign sel[5] = A[5] & ~(A[7]|A[6]);
assign sel[4] = A[4] & ~(A[7]|A[6]|A[5]);
